local keywordHandler = KeywordHandler:new()
local npcHandler = NpcHandler:new(keywordHandler)
npcType.onThink = function(npc, interval) npcHandler:onThink(npc, interval) end
npcType.onAppear = function(npc, creature) npcHandler:onAppear(npc, creature) end
npcType.onDisappear = function(npc, creature) npcHandler:onDisappear(npc, creature) end
npcType.onMove = function(npc, creature, from, to) npcHandler:onMove(npc, creature, from, to) end
npcType.onSay = function(npc, creature, type, message) npcHandler:onSay(npc, creature, type, message) end
npcType.onCloseChannel = function(npc, player) npcHandler:onCloseChannel(npc, player) end
npcType.onBuyItem = function(npc, player, itemId, subType, amount, ignore, inBackpacks, totalCost)
	npc:sellItem(player, itemId, amount, subType, 0, ignore, inBackpacks)
end
npcType.onSellItem = function(npc, player, itemId, subtype, amount, ignore, name, totalCost)
	player:sendTextMessage(MESSAGE_TRADE, string.format("Sold %ix %s for %i gold.", amount, name, totalCost))
end
npcType.onCheckItem = function(npc, player, clientId, subType) end

-- Murderers (red/black) get no service in town (DESIGN.md 6.4)
local function refuseMurderers(npc, player)
	if SpirePvP and SpirePvP.isMurderer(player) then
		npcHandler:say("I don't deal with murderers. Get out.", npc, player)
		return false
	end
	return true
end

keywordHandler:addKeyword({ "job" }, StdModule.say, { npcHandler = npcHandler, text = "The trader of the hearth. Ask me for a {trade}." })

npcHandler:setMessage(MESSAGE_GREET, "Back from the field, |PLAYERNAME|? I buy nearly everything monsters drop: gear, hides, gems, odds and ends. Ask for a {trade} and sell me your loot.")
npcHandler:setMessage(MESSAGE_FAREWELL, "Good climbing, |PLAYERNAME|.")
npcHandler:setMessage(MESSAGE_WALKAWAY, "Good climbing.")
npcHandler:setCallback(CALLBACK_GREET, refuseMurderers)
npcHandler:setCallback(CALLBACK_MESSAGE_DEFAULT, function(npc, player, type, msg)
	if SpireCraft and SpireCraft.talk(npc, npcHandler, player, msg, npcConfig.name) then
		return false
	end
	if SpireHunt and MsgContains(msg, "hunt") then
		npcHandler:say(SpireHunt.advice(player:getLevel()), npc, player)
		return false
	end
	return true
end)
npcHandler:addModule(FocusModule:new(), npcConfig.name, true, true, true)
npcType:register(npcConfig)
